export type ParsedRedeemInstruction<
  TProgram extends string = typeof REDEMPTION_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    authority: TAccountMetas[0];
    redemptionConfig: TAccountMetas[1];
    mint: TAccountMetas[2];
    vaultAuthority: TAccountMetas[3];
    vault: TAccountMetas[4];
    redemptionRecord: TAccountMetas[5];
    tokenProgram: TAccountMetas[6];
    payer: TAccountMetas[7];
    systemProgram: TAccountMetas[8];
  };
  data: RedeemInstructionData;
};

export function parseRedeemInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRedeemInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 9) {
    // TODO: Coded error.
    throw new Error("Not enough accounts");
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      authority: getNextAccount(),
      redemptionConfig: getNextAccount(),
      mint: getNextAccount(),
      vaultAuthority: getNextAccount(),
      vault: getNextAccount(),
      redemptionRecord: getNextAccount(),
      tokenProgram: getNextAccount(),
      payer: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getRedeemInstructionDataDecoder().decode(instruction.data),
  };
}
